PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY);
CREATE TABLE organizations(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE campaigns(id TEXT PRIMARY KEY, org TEXT NOT NULL REFERENCES organizations, name TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password TEXT NOT NULL);
CREATE TABLE grants(user_id TEXT REFERENCES users, campaign TEXT REFERENCES campaigns, role TEXT NOT NULL CHECK(role IN('producer','approver','facilitator','investigator')), expires INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,campaign,role));
CREATE TABLE versions(id INTEGER PRIMARY KEY, campaign TEXT NOT NULL REFERENCES campaigns, number INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN('DRAFT','IN_REVIEW','CHANGES_REQUESTED','APPROVED','PUBLISHED','REVOKED')), content TEXT NOT NULL, author TEXT NOT NULL REFERENCES users, revision INTEGER NOT NULL DEFAULT 0, UNIQUE(campaign,number));
CREATE TABLE assets(id TEXT PRIMARY KEY, version INTEGER NOT NULL REFERENCES versions, classification TEXT NOT NULL, provenance TEXT NOT NULL, rights TEXT NOT NULL, hash TEXT NOT NULL, bytes INTEGER NOT NULL);
CREATE TABLE briefings(id TEXT PRIMARY KEY, campaign TEXT NOT NULL REFERENCES campaigns, version INTEGER NOT NULL REFERENCES versions, facilitator TEXT NOT NULL REFERENCES users, scheduled TEXT, state TEXT NOT NULL DEFAULT 'SCHEDULED' CHECK(state IN('SCHEDULED','READY','ACTIVE','PAUSED','COMPLETED','ABORTED','CANCELLED')), stage INTEGER NOT NULL DEFAULT 0 CHECK(stage BETWEEN 0 AND 5), elapsed INTEGER NOT NULL DEFAULT 0, running_since INTEGER, revealed INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE invitations(id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, briefing TEXT NOT NULL REFERENCES briefings, version INTEGER NOT NULL REFERENCES versions, audience TEXT NOT NULL CHECK(audience IN('participant','presentation')), expires INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE logins(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users, csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE evidence(briefing TEXT PRIMARY KEY REFERENCES briefings, version INTEGER NOT NULL REFERENCES versions, state TEXT NOT NULL CHECK(state IN('READY_FOR_REVIEW','APPROVED_FOR_RELEASE','RELEASED')), revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE approvals(id INTEGER PRIMARY KEY, campaign TEXT NOT NULL REFERENCES campaigns, version INTEGER NOT NULL REFERENCES versions, actor TEXT NOT NULL REFERENCES users, scope TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE releases(id INTEGER PRIMARY KEY, campaign TEXT NOT NULL REFERENCES campaigns, version INTEGER NOT NULL REFERENCES versions, briefing TEXT NOT NULL UNIQUE REFERENCES briefings, actor TEXT NOT NULL REFERENCES users, created INTEGER NOT NULL, supersedes INTEGER REFERENCES releases);
CREATE TABLE audit(id INTEGER PRIMARY KEY, campaign TEXT NOT NULL REFERENCES campaigns, actor TEXT NOT NULL, action TEXT NOT NULL, version INTEGER NOT NULL REFERENCES versions, created INTEGER NOT NULL);
CREATE TABLE receipts(actor TEXT NOT NULL, key TEXT NOT NULL, target TEXT NOT NULL, PRIMARY KEY(actor,key));
CREATE TABLE login_attempts(address TEXT PRIMARY KEY, count INTEGER NOT NULL, reset INTEGER NOT NULL);
CREATE TRIGGER immutable_approval_update BEFORE UPDATE ON approvals BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER immutable_approval_delete BEFORE DELETE ON approvals BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER immutable_release_update BEFORE UPDATE ON releases BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER immutable_release_delete BEFORE DELETE ON releases BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER immutable_audit_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER immutable_audit_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'immutable'); END;
CREATE TRIGGER immutable_content BEFORE UPDATE OF content,author,number,campaign ON versions WHEN OLD.status NOT IN('DRAFT','CHANGES_REQUESTED') BEGIN SELECT RAISE(ABORT,'reviewed content is immutable'); END;
INSERT INTO migrations VALUES(1);
